import xml.etree.ElementTree as ET

def fetch_page(start):
    query = 'all:multimodal%20OR%20all:RAG'
    url = "http://export.arxiv.org/api/query?search_query=" + query + "&start=" + str(start) + "&max_results=25&sortBy=submittedDate&sortOrder=descending"
    return web_fetch(url=url)

NS = {'atom': 'http://www.w3.org/2005/Atom'}

def is_multimodal_rag_paper(title, summary):
    txt = (title + " " + summary).lower()
    multimodal = ['multimodal', 'vision', 'visual', 'image', 'video', 'audio',
                  'speech', 'cross-modal', 'crossmodal', 'vlm', 'vision-language',
                  'vision language', 'graph', 'document', 'table', 'chart']
    rag = ['rag', 'retrieval-augmented', 'retrieval augmented', 'retrieval based']
    return any(k in txt for k in multimodal) and any(k in txt for k in rag)

papers = []
page_start = 0
max_pages = 10

while len(papers) < 5 and page_start < max_pages * 25:
    resp = fetch_page(page_start)
    if resp.get('status') != 200:
        break
    root = ET.fromstring(resp['content'])
    for entry in root.findall('atom:entry', NS):
        title_el = entry.find('atom:title', NS)
        summary_el = entry.find('atom:summary', NS)
        updated_el = entry.find('atom:updated', NS)
        id_el = entry.find('atom:id', NS)
        link_el = None
        for l in entry.findall('atom:link', NS):
            if l.get('rel') == 'alternate' and l.get('type') == 'text/html':
                link_el = l.get('href')
                break
        if None in (title_el, summary_el, updated_el, id_el, link_el):
            continue
        title = title_el.text.strip()
        summary = ' '.join(summary_el.text.strip().split())
        updated = updated_el.text.strip()[:10]
        arxiv_id = id_el.text.strip()
        if is_multimodal_rag_paper(title, summary):
            papers.append({
                'title': title,
                'date': updated,
                'summary': summary,
                'link': link_el
            })
            if len(papers) >= 5:
                break
    page_start += 25

def build_markdown(papers):
    header = "| Rank | Title | Date | Summary |\n|------|-------|------|---------|\n"
    rows = []
    for i, p in enumerate(papers, 1):
        clean = ' '.join(p['summary'].split())
        if len(clean) > 150:
            clean = clean[:147] + "..."
        rows.append(f"| {i} | {p['title']} | {p['date']} | {clean} |")
    return header + "\n".join(rows)

with open('papers.md', 'w', encoding='utf-8') as f:
    f.write(build_markdown(papers))

print(f'Wrote {len(papers)} papers to papers.md')
finish(summary='Collected 5 recent multimodal RAG papers from arXiv and saved a markdown comparison table to papers.md')
